import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.BOeh4kYD.js";const g=JSON.parse('{"title":"凭证、并发与恢复：实验方法与逐轮结果","description":"","frontmatter":{"title":"凭证、并发与恢复：实验方法与逐轮结果","date":"2026-09-10T00:00:00.000Z"},"headers":[],"relativePath":"zh/research/evidence/2026-09-10-authority-scope.md","filePath":"zh/research/evidence/2026-09-10-authority-scope.md","lastUpdated":1789010966000}'),l={name:"zh/research/evidence/2026-09-10-authority-scope.md"};function o(n,t,i,h,s,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="实验附件-对象、作用域与证据边界" tabindex="-1">实验附件：对象、作用域与证据边界 <a class="header-anchor" href="#实验附件-对象、作用域与证据边界" aria-label="Permalink to &quot;实验附件：对象、作用域与证据边界&quot;">​</a></h1><p>所有凭证均为固定合成字符串；没有访问真实密钥、连接模型、操作生产数据库或向外部服务试写。上游源码未修改；Python 方法抽取、TypeScript 类型擦除、依赖接缝均在探针内可审查。</p><h2 id="a-·-ag2-同一上限-两个统计范围" tabindex="-1">A · AG2：同一上限，两个统计范围 <a class="header-anchor" href="#a-·-ag2-同一上限-两个统计范围" aria-label="Permalink to &quot;A · AG2：同一上限，两个统计范围&quot;">​</a></h2><p>来源：<a href="https://github.com/ag2ai/ag2/pull/3243" target="_blank" rel="noreferrer">#3243</a>。base <code>33779766a2e5040b0f0feb80cd4dd50c24d1e07c</code>；head <code>5487973dabc47a383a9c268a121f8de3084ec122</code>。</p><p>实际执行 <code>Agent._spawn_subtask</code> 原方法；初始化字段为与版本相符的夹具，任务正文替换为可等待的计数协程。双循环时，A1 先进入，B1 在另一个真实 OS 线程进入，然后 A 再申请 A2，最后统一释放。这个交错直接检验旧单槽引用是否被另一个循环替换，不依赖随机抢占。</p><table tabindex="0"><thead><tr><th>版本 / 执行域</th><th style="text-align:right;">A 循环峰值</th><th style="text-align:right;">B 循环峰值</th><th style="text-align:right;">全局峰值</th></tr></thead><tbody><tr><td>base / 单循环</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>base / 双循环</td><td style="text-align:right;">2</td><td style="text-align:right;">1</td><td style="text-align:right;">3</td></tr><tr><td>head / 单循环</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>head / 双循环</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">2</td></tr></tbody></table><p>每种配置每轮 5 次，2 轮共 40 次受控试验，逐次结果一致；无异常。它证明所测方法在这个交错下的局部与合计行为，不是完整 Agent、模型调用或分布式负载测试。</p><p>复跑：<code>python probe-ag2.py 3</code>。结果：<a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/runs/ag2-1.json" target="_blank" rel="noreferrer">第1轮</a>、<a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/runs/ag2-2.json" target="_blank" rel="noreferrer">第2轮</a>。</p><h2 id="b-·-openhands-同一秘密-不同传递路径" tabindex="-1">B · OpenHands：同一秘密，不同传递路径 <a class="header-anchor" href="#b-·-openhands-同一秘密-不同传递路径" aria-label="Permalink to &quot;B · OpenHands：同一秘密，不同传递路径&quot;">​</a></h2><p>#4927 base <code>7a018907c9b6cac2ee7b205a1b4a5e3e0228e8e4</code>；head <code>cf1283ca0690d333cbdf0bd7d90b42d16583cb58</code>。#4931 head <code>3c51d02d5b224c45664408b1b164b5843b98922e</code>。</p><p>执行原 <code>_active_file_secrets</code>、<code>_present_file_secret_names</code>、<code>_strip_conflicting_env</code>，以及启动方法中连续的环境构造代码。两个版本共用从 head 固定源文件语法树提取的注册表元数据；提供方身份由夹具直接指定，未验证命令探测。注册表导出与文件写入为接缝夹具，文件端只统计回调，不声称创建了真实认证文件。最终环境交给真实 Python 子进程，子进程只返回变量名。四种文件型模拟秘密为 Codex、Gemini、Kimi、Pi 注册表声明的名字。</p><table tabindex="0"><thead><tr><th>版本 / 提供方</th><th style="text-align:right;">文件物化回调数</th><th style="text-align:right;">子进程中的四类 blob 变量数</th></tr></thead><tbody><tr><td>base / Claude</td><td style="text-align:right;">4</td><td style="text-align:right;">0</td></tr><tr><td>base / Codex</td><td style="text-align:right;">4</td><td style="text-align:right;">0</td></tr><tr><td>base / 未识别</td><td style="text-align:right;">4</td><td style="text-align:right;">0</td></tr><tr><td>head / Claude</td><td style="text-align:right;">0</td><td style="text-align:right;">4</td></tr><tr><td>head / Codex</td><td style="text-align:right;">1</td><td style="text-align:right;">3</td></tr><tr><td>head / 未识别</td><td style="text-align:right;">4</td><td style="text-align:right;">0</td></tr></tbody></table><p>再把 #4931 的原配置过滤函数接到 #4927 环境片段前面，作为<strong>跨 PR 实验组合</strong>，不是两者已经合并的 SDK：</p><table tabindex="0"><thead><tr><th>Claude ACP 配置</th><th>过滤后注册表中的名称</th></tr></thead><tbody><tr><td><code>null</code></td><td>四类 blob、<code>ANTHROPIC_API_KEY</code>、<code>PROD_DB_URL</code></td></tr><tr><td><code>[]</code></td><td><code>ANTHROPIC_API_KEY</code></td></tr><tr><td><code>[PROD_DB_URL]</code></td><td><code>ANTHROPIC_API_KEY</code>、<code>PROD_DB_URL</code></td></tr></tbody></table><p>以上所有 ACP 环境场景仍携带装置中的 <code>PLATFORM_INTERNAL_SENTINEL</code>，因为该入口在注册表过滤之外。另设普通 OpenHands 配置空列表对照，只运行配置过滤函数，所得集合为空；<strong>没有将此对照解释为普通 OpenHands 子进程测试</strong>。</p><p>两轮各 10 个场景，结果一致。先前装置启动失败及修正见 <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/runs/harness-notes.md" target="_blank" rel="noreferrer">装置记录</a>。我们没有真实 CLI 握手、SDK 服务端、认证、模型输出或秘密外泄证据。</p><p>复跑：<code>python probe-openhands.py 3</code>。结果：<a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/runs/openhands-1.json" target="_blank" rel="noreferrer">第1轮</a>、<a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/runs/openhands-2.json" target="_blank" rel="noreferrer">第2轮</a>。</p><h2 id="c-·-orca-恢复动作与预算释放读取两份索引" tabindex="-1">C · Orca：恢复动作与预算释放读取两份索引 <a class="header-anchor" href="#c-·-orca-恢复动作与预算释放读取两份索引" aria-label="Permalink to &quot;C · Orca：恢复动作与预算释放读取两份索引&quot;">​</a></h2><p>来源：<a href="https://github.com/stablyai/orca/pull/19745" target="_blank" rel="noreferrer">#19745</a>。base <code>b94bcdc632a9af756f2c43e7e4b4c3b8930f75eb</code>；head <code>7af0f109537e5f39aee532690ec4a16b3d58f9fb</code>。</p><p>运行完整恢复模块和对象查找模块，擦除 TypeScript 类型并替换导入。计时、定时器、store 外壳、PTY 和日志为夹具；真实 remount 函数更新内存中终端行的 generation。没有启动 Electron，没有复现显存耗尽。</p><table tabindex="0"><thead><tr><th>场景</th><th style="text-align:right;">请求次数</th><th style="text-align:right;">base 恢复数</th><th style="text-align:right;">head 恢复数</th></tr></thead><tbody><tr><td>两索引一致，间隔 10ms</td><td style="text-align:right;">200</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr><tr><td>终端行存在、UI 索引缺失，间隔 10ms</td><td style="text-align:right;">200</td><td style="text-align:right;">200</td><td style="text-align:right;">1</td></tr><tr><td>同上，间隔 16s</td><td style="text-align:right;">10</td><td style="text-align:right;">10</td><td style="text-align:right;">3</td></tr><tr><td>模拟真正关闭并重新建行</td><td style="text-align:right;">2</td><td style="text-align:right;">2</td><td style="text-align:right;">2</td></tr><tr><td>0/16/32/48/300.001 秒申请</td><td style="text-align:right;">5</td><td style="text-align:right;">4</td><td style="text-align:right;">4</td></tr><tr><td>第一轮成功后重放旧 generation</td><td style="text-align:right;">2</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr></tbody></table><p>两轮各 12 个版本/场景结果一致。10ms 对照体现冷却记录被清除，16s 对照体现五分钟累计上限被清除；二者不可合并为同一种计数。</p><p>上游报告的 8 个 tab、122.4 秒、8,878 次 remount 属于作者事故材料，本轮没有取得原始崩溃包，不能当作我们的实测。</p><p>复跑：<code>node probe-orca.mjs 3</code>。结果：<a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/runs/orca-1.json" target="_blank" rel="noreferrer">第1轮</a>、<a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/runs/orca-2.json" target="_blank" rel="noreferrer">第2轮</a>。</p><h2 id="d-·-paperclip-终止请求与退出事实" tabindex="-1">D · Paperclip：终止请求与退出事实 <a class="header-anchor" href="#d-·-paperclip-终止请求与退出事实" aria-label="Permalink to &quot;D · Paperclip：终止请求与退出事实&quot;">​</a></h2><p>来源：<a href="https://github.com/paperclipai/paperclip/pull/13119" target="_blank" rel="noreferrer">#13119</a>，head <code>7dd170d83f251464f882e7028afb51c9805845b7</code>。</p><p>直接加载 <code>local-process-control.ts</code> 原模块，启动一个只等待的 Node 子进程。模块捕获到了同一个 ChildProcess 句柄；终止请求返回 true 的当下，退出证据仍为 false；收到 exit 事件后为 true，重复终止返回 false，捕获表已移除该句柄。未知句柄不会被认定为已退出。两轮结果相同。</p><p>这仅验证单一子进程的捕获与退出观察。没有验证子孙进程、工具副作用停止、ACP continuation、新凭证注入或业务可重试性，故不单独包装成长篇“Stop 已安全”文章。</p><p>复跑：<code>node probe-paperclip.mjs 3</code>。结果：<a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/runs/paperclip-1.json" target="_blank" rel="noreferrer">第1轮</a>、<a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/runs/paperclip-2.json" target="_blank" rel="noreferrer">第2轮</a>。</p><h2 id="来源与完整性" tabindex="-1">来源与完整性 <a class="header-anchor" href="#来源与完整性" aria-label="Permalink to &quot;来源与完整性&quot;">​</a></h2><p><code>sources/index.json</code> 保存核查时的 PR 状态；<code>sources/code-manifest.json</code> 固定源文件 URL、提交 SHA 与 SHA-256。公开包的 <code>fetch-pinned.mjs</code> 按固定 URL 获取并核验上游原始源码；<code>verify-public.mjs</code> 比较两轮输出及探针哈希，添加 <code>--sources</code> 可校验已下载源码。完整性检查不等于重新执行实验。</p><h2 id="公开复核入口" tabindex="-1">公开复核入口 <a class="header-anchor" href="#公开复核入口" aria-label="Permalink to &quot;公开复核入口&quot;">​</a></h2><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope" target="_blank" rel="noreferrer">实验记录与复跑脚本</a> · <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-10-authority-scope/sources/code-manifest.json" target="_blank" rel="noreferrer">固定源文件清单</a> · <a href="/joinwell52/en/research/evidence/2026-09-10-authority-scope">English evidence guide</a></p><p>公开包不再分发上游完整源码。先运行 <code>node fetch-pinned.mjs</code>，按固定 URL 获取并核验原始字节，再运行相应探针。Python 3.10 与 Node 24.16.0 是本轮实际解释器。绘图另需 Matplotlib 与 Pillow；它们不是运行探针的依赖。保存的第 1、2 轮保持不变，新运行请用第 3 轮或其他新编号。</p>',34)])])}const u=e(l,[["render",o]]);export{g as __pageData,u as default};
